// POSIX normpath: collapse slashes, drop ".", resolve ".." lexically, keep exactly two leading slashes.
string normpath(const string &path) {
    if (path.empty()) return ".";
    size_t lead = 0;
    while (lead < path.size() && path[lead] == '/') lead++;
    string prefix = lead == 0 ? "" : (lead == 2 ? "//" : "/");
    vector<string> comps;
    stringstream ss(path);
