    while (getline(ss, c, '/')) {
        if (c.empty() || c == ".") continue;
        if (c != ".." || (prefix.empty() && comps.empty()) || (!comps.empty() && comps.back() == ".."))
            comps.push_back(c);
        else if (!comps.empty())
            comps.pop_back();
    }
    string out = prefix;
    for (size_t i = 0; i < comps.size(); i++) out += (i ? "/" : "") + comps[i];
    return out.empty() ? "." : out;
