// True when p is a strict descendant of root: commonpath([root, p]) == root and p != root.
bool inside(const string &root, const string &p) {
    bool ar = !root.empty() && root[0] == '/', ap = !p.empty() && p[0] == '/';
    if (ar != ap) return false;  // commonpath refuses to mix absolute and relative paths
    vector<string> a = parts(root), b = parts(p);
