bool validIp(const string &t) {
    vector<string> seg;
    size_t start = 0;
    while (true) {
        size_t d = t.find('.', start);
        seg.push_back(t.substr(start, d == string::npos ? string::npos : d - start));
        if (d == string::npos) break;
        start = d + 1;
    }
    if (seg.size() != 4) return false;
    for (auto &x : seg) {
        if (x.empty() || x.size() > 3) return false;
        for (char ch : x)
