public class Main {
    // POSIX normpath: collapse slashes, drop ".", resolve ".." lexically, keep exactly two leading slashes.
    static String normpath(String path) {
        if (path.isEmpty()) return ".";
        int lead = 0;
        while (lead < path.length() && path.charAt(lead) == '/') lead++;
        String prefix = lead == 0 ? "" : (lead == 2 ? "//" : "/");
        ArrayList<String> comps = new ArrayList<>();
        for (String c : path.split("/")) {
            if (c.isEmpty() || c.equals(".")) continue;
            if (!c.equals("..") || (prefix.isEmpty() && comps.isEmpty()) || (!comps.isEmpty() && comps.get(comps.size() - 1).equals("..")))
                comps.add(c);
            else if (!comps.isEmpty())
                comps.remove(comps.size() - 1);
        }
        String out = prefix + String.join("/", comps);
        return out.isEmpty() ? "." : out;
    }

    static List<String> parts(String p) {
        List<String> v = new ArrayList<>();
        for (String c : p.split("/")) if (!c.isEmpty() && !c.equals(".")) v.add(c);
        return v;
    }

    // True when p is a strict descendant of root: commonpath([root, p]) == root and p != root.
    static boolean inside(String root, String p) {
        boolean ar = root.startsWith("/"), ap = p.startsWith("/");
        if (ar != ap) return false;  // commonpath refuses to mix absolute and relative paths
        List<String> a = parts(root), b = parts(p);
        int k = 0;
        while (k < a.size() && k < b.size() && a.get(k).equals(b.get(k))) k++;
        String common = (ar ? "/" : "") + String.join("/", a.subList(0, k));
        return common.equals(root) && !p.equals(root);
    }

    static boolean validIp(String t) {
        String[] seg = t.split("\\.", -1);
        if (seg.length != 4) return false;
        for (String x : seg) {
            if (x.isEmpty() || x.length() > 3) return false;
            for (int i = 0; i < x.length(); i++) if (x.charAt(i) < '0' || x.charAt(i) > '9') return false;
            if (x.length() > 1 && x.charAt(0) == '0') return false;  // no leading zeros except "0"
            if (Integer.parseInt(x) > 255) return false;
        }
        return true;
    }

    static boolean isSpace(char ch) {
        return Character.isWhitespace(ch) || ch == '\u0085' || ch == ' ' || ch == ' ' || ch == ' ';
    }

    public static void main(String[] args) throws IOException {
        String data = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        String[] lines = data.split("\r?\n", -1);
        String root = normpath(lines[0]);
        int n = Integer.parseInt(lines[1].trim());
        ArrayList<String> out = new ArrayList<>();
        for (int i = 2; i < 2 + n && i < lines.length; i++) {
            int tab = lines[i].indexOf('\t');
            if (tab < 0) continue;
            if (!inside(root, normpath(lines[i].substring(0, tab)))) continue;
            // Split content on whitespace and keep every valid IPv4 occurrence.
            String content = lines[i].substring(tab + 1);
            int k = 0, len = content.length();
            while (k < len) {
                while (k < len && isSpace(content.charAt(k))) k++;
                int s = k;
                while (k < len && !isSpace(content.charAt(k))) k++;
                if (k > s) {
                    String tok = content.substring(s, k);
                    if (validIp(tok)) out.add(tok);
                }
            }
        }
        Collections.sort(out);
        StringBuilder sb = new StringBuilder();
        for (String s : out) sb.append(s).append('\n');
        System.out.print(sb);
    }
