import (
	"bufio"
	"io"
	"os"
	"sort"
	"strings"
)

// POSIX normpath: collapse slashes, drop ".", resolve ".." lexically, keep exactly two leading slashes.
func normpath(path string) string {
	if path == "" {
		return "."
	}
	lead := len(path) - len(strings.TrimLeft(path, "/"))
	prefix := ""
	if lead == 2 {
		prefix = "//"
	} else if lead > 0 {
		prefix = "/"
	}
	comps := []string{}
	for _, c := range strings.Split(path, "/") {
		if c == "" || c == "." {
			continue
		}
		if c != ".." || (prefix == "" && len(comps) == 0) || (len(comps) > 0 && comps[len(comps)-1] == "..") {
			comps = append(comps, c)
		} else if len(comps) > 0 {
			comps = comps[:len(comps)-1]
		}
	}
	out := prefix + strings.Join(comps, "/")
	if out == "" {
		return "."
	}
	return out
}

func parts(p string) []string {
	v := []string{}
	for _, c := range strings.Split(p, "/") {
		if c != "" && c != "." {
			v = append(v, c)
		}
	}
	return v
}

// True when p is a strict descendant of root: commonpath([root, p]) == root and p != root.
func inside(root, p string) bool {
	ar, ap := strings.HasPrefix(root, "/"), strings.HasPrefix(p, "/")
	if ar != ap {
		return false // commonpath refuses to mix absolute and relative paths
	}
	a, b := parts(root), parts(p)
	k := 0
	for k < len(a) && k < len(b) && a[k] == b[k] {
		k++
	}
	common := strings.Join(a[:k], "/")
	if ar {
		common = "/" + common
	}
	return common == root && p != root
}

func validIP(t string) bool {
	seg := strings.Split(t, ".")
	if len(seg) != 4 {
		return false
	}
	for _, x := range seg {
		if x == "" || len(x) > 3 {
			return false
		}
		v := 0
		for i := 0; i < len(x); i++ {
			if x[i] < '0' || x[i] > '9' {
				return false
			}
			v = v*10 + int(x[i]-'0')
		}
		if (len(x) > 1 && x[0] == '0') || v > 255 { // no leading zeros except "0"
			return false
		}
	}
	return true
}

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	root := normpath(lines[0])
	n := 0
	for _, ch := range strings.TrimSpace(lines[1]) {
		n = n*10 + int(ch-'0')
	}
	out := []string{}
	for i := 2; i < 2+n && i < len(lines); i++ {
		tab := strings.IndexByte(lines[i], '\t')
		if tab < 0 || !inside(root, normpath(lines[i][:tab])) {
			continue
		}
		// Split content on whitespace and keep every valid IPv4 occurrence.
		for _, tok := range strings.Fields(lines[i][tab+1:]) {
			if validIP(tok) {
				out = append(out, tok)
			}
		}
	}
	sort.Strings(out)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for _, s := range out {
		w.WriteString(s + "\n")
	}
}
